-- PLANETAI submission verification and private employer access tokens
-- Token values are generated by trusted server functions and only SHA-256 hashes
-- are stored here. This table must never be exposed to anonymous browser clients.

create table if not exists public.job_submission_tokens (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.job_submissions(id) on delete cascade,
  purpose text not null
    check (purpose in ('email_verification', 'employer_management')),
  token_hash char(64) not null unique,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists job_submission_tokens_active_lookup_idx
  on public.job_submission_tokens(token_hash, purpose, expires_at)
  where consumed_at is null;

create index if not exists job_submission_tokens_submission_idx
  on public.job_submission_tokens(submission_id, purpose, created_at desc);

alter table public.job_submission_tokens enable row level security;

-- No browser role may read or write private access tokens. Trusted server
-- functions use the Supabase service-role key, which must remain server-side.
revoke all on table public.job_submission_tokens from anon, authenticated;
revoke all on table public.job_submission_tokens from public;

-- The admin predicate is only needed by authenticated admin policies.
revoke all on function public.is_planetai_admin() from public;
revoke all on function public.is_planetai_admin() from anon;
grant execute on function public.is_planetai_admin() to authenticated;
